asm_1_268_gzf_row:
            ld a, (var_guiscr_cx0)
            ld (gz_cx), a
asm_1_268_gzf_cell:
            ld a, (gz_cy)               ; the cell's top byte: #8000 + cy * 80 + cx
            ld l, a
            ld h, 0
            add hl, hl
            add hl, hl
            add hl, hl
            add hl, hl                  ; * 16
            ld d, h
            ld e, l
            add hl, hl
            add hl, hl                  ; * 64
            add hl, de                  ; * 80
            ld a, (gz_cx)
            ld e, a
            ld d, #80
            add hl, de
            ld de, gz_cb                ; its 8 bytes (#800 apart) to gz_cb
            ld b, 8
asm_1_268_gzf_g:      ld a, (hl)
            ld (de), a
            inc de
            ld a, h
            add a, 8
            ld h, a
            djnz asm_1_268_gzf_g
            call gz_tile                ; A = its tile
            push af
            ld a, (gz_cy)               ; the tilemap: #C000 + (cy + 4) * 80 + cx
            add a, 4
            ld l, a
            ld h, 0
            add hl, hl
            add hl, hl
            add hl, hl
            add hl, hl
            ld d, h
            ld e, l
            add hl, hl
            add hl, hl
            add hl, de
            ld a, (gz_cx)
            ld e, a
            ld d, #C0
            add hl, de
            pop af
            ld (hl), a
            ld a, (gz_cx)
            ld hl, var_guiscr_cx1
            cp (hl)
            inc a
            ld (gz_cx), a
            jr c, asm_1_268_gzf_cell
            ld a, (gz_cy)
            ld hl, var_guiscr_cy1
            cp (hl)
            inc a
            ld (gz_cy), a
            jr c, asm_1_268_gzf_row
            call gz_unmap
            jp asm_1_268_gz_end
; gz_tile: the tile for the 8 bytes at gz_cb - A. 0 for a blank cell; else the hash table's
; (#E000, 1024 places: the tile, 0 empty - under the stub, #E000-#EEFF), its copy at #E400 + tile * 8 to
; compare; a new one: the next free (gz_nt), its bytes to #E400 and to the tiles (#CA00: slot 6
; is page 10 now). None free: 0 and the full flag (#EC00)
@gz_tile:
            ld hl, gz_cb
            ld b, 8
            xor a
asm_1_268_gzh_z:      or (hl)
            inc hl
            djnz asm_1_268_gzh_z
            or a
            ret z                       ; (all 8 bytes 0: tile 0)
            ld hl, gz_cb
            ld b, 8
            xor a
            ld c, a
asm_1_268_gzh_lp:     rlca
            xor (hl)
            ld e, a
            ld a, c
            add a, (hl)
            ld c, a
            ld a, e
            inc hl
            djnz asm_1_268_gzh_lp
            ld e, a                     ; DE = the place: A + (the sum's low 2 bits) * 256
            ld a, c
            and 3
            ld d, a
asm_1_268_gzh_probe:
            ld hl, #E000
            add hl, de
            ld a, (hl)
            or a
            jr z, asm_1_268_gzh_new
            ld (gz_t), a                ; compare with that tile's copy
            push hl
            ld l, a
            ld h, 0
            add hl, hl
            add hl, hl
            add hl, hl
            ld bc, #E400
            add hl, bc
            ld bc, gz_cb
            push de
            ld e, 8
asm_1_268_gzh_cmp:    ld a, (bc)
            cp (hl)
            jr nz, asm_1_268_gzh_ne
            inc hl
            inc bc
            dec e
            jr nz, asm_1_268_gzh_cmp
            pop de
            pop hl
            ld a, (gz_t)
            ret
asm_1_268_gzh_ne:     pop de
            pop hl
            inc de
            ld a, d
            and 3
            ld d, a
            jr asm_1_268_gzh_probe
asm_1_268_gzh_new:
            ld a, (gz_nt)
            or a
            jr nz, asm_1_268_gzh_room
            ld a, 1
            ld (#EC00), a
            xor a
            ret
asm_1_268_gzh_room:
            ld (hl), a                  ; the table's place: this tile
            ld (gz_t), a
            inc a
            ld (gz_nt), a               ; (256: 0 - full from now on)
            ld a, (gz_t)
            ld l, a
            ld h, 0
            add hl, hl
            add hl, hl
            add hl, hl
            push hl
            ld bc, #E400
            add hl, bc
            ex de, hl
            ld hl, gz_cb
            ld bc, 8
            ldir
            pop hl
            ld bc, #CA00
            add hl, bc
            ex de, hl
            ld hl, gz_cb
            ld bc, 8
            ldir
            ld a, (gz_t)
            ret
; gz_down: HL one pixel line down in the shadow (#800 on; past a row's 8th line back #4000, on #50)
@gz_down:
            ld a, h
            add a, 8
            ld h, a
            and #38
            ret nz
            ld a, l
            add a, #50
            ld l, a
            ld a, h
            adc a, #C0
            ld h, a
            ret
; gz_map / gz_unmap: bank 5's page 10 in MMU slot 6 (#C000), GUI's own page back
@gz_map:
            ld bc, #243B
            ld a, #56
            out (c), a
            inc b
            in a, (c)
            ld (gz_m6), a
            ld a, 10
            out (c), a
            ret
@gz_unmap:
            ld bc, #243B
            ld a, #56
            out (c), a
            inc b
            ld a, (gz_m6)
            out (c), a
            ret
@gz_m6:      db 0
@gz_nt:      db 1                        ; the next free tile (0 after 255: none)
@gz_t:       db 0
@gz_h:       db 0
@gz_cx:      db 0
@gz_cy:      db 0
@gz_cb:      ds 8
            ASSERT ntc_free <= #7D00, "GUI (Next) must end below #7D00 (its font copy; the shadow picture at #8000, the tile cache at #E000)"
asm_1_268_gz_end:
            ld sp, (var_guiscr_hsp)
			ret			; end of #asm

fn_guiscr_fontcopy:		; sub fontcopy (asm keyword), GuiScr.cls line 488
            ld bc, #243B
            ld a, #56
            out (c), a
            inc b
            in a, (c)
            ld (fn_guiscr_fontcopy_gz_m6b), a
            ld a, 11
            out (c), a
            ld hl, #C000 + #0C00 + 32 * 8
            ld de, #7D00
            ld bc, 96 * 8
            ldir
            ld bc, #243B
            ld a, #56
            out (c), a
            inc b
            ld a, (fn_guiscr_fontcopy_gz_m6b)
            out (c), a
            jr fn_guiscr_fontcopy_gz_fend
fn_guiscr_fontcopy_gz_m6b:     db 0
fn_guiscr_fontcopy_gz_fend:
			ret			; end of #asm

asm_2_231:		; #asm, CybSys.cls line 231
            ld (var_cybsys_hsp), sp
            ld sp, (ntc_csp)
            ld a, (var_cybsys_bdos_f)
            ld c, a
            ld de, (var_cybsys_bdos_d)
            ei                      ; (CP/M's BDOS: interrupts on)
            call 5
            di                      ; (off before SP is the threaded code again: it comes back with them on)
            ld l, a
            ld h, 0
            ld (var_cybsys_bdos_bdos), hl
            ld sp, (var_cybsys_hsp)
			ret			; end of #asm

fn_system_commandline:		; function commandline (asm keyword), System.cls line 68
            pop hl
            jp ntc_cmdget
			ret			; end of #asm


